"""Core data models for Face_Pipeline_V2.

All data objects are immutable frozen dataclasses per AISDD 02 design specification.
Stage communication is exclusively through these data objects.
"""

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, Optional, Tuple, Union

import numpy as np


# ============================================================================
# Video Data Models (AISDD 2.5)
# ============================================================================


@dataclass(frozen=True)
class VideoInfo:
    """视频基础信息 — Generated by Stage 0 Video Integrity Check.

    Fields are defined per AISDD 2.5.1.
    """

    video_id: str
    """视频唯一ID — 视频数据唯一标识"""
    video_path: Path
    """视频路径 — 原始视频文件路径"""
    original_fps: float
    """原始帧率 — 输入视频原始FPS"""
    width: int
    """视频宽度 — 原始视频宽度"""
    height: int
    """视频高度 — 原始视频高度"""
    duration: float
    """视频时长 — 视频总时长(秒)"""
    total_frames: int
    """总帧数 — 视频总帧数量"""
    codec: str
    """编码格式 — 视频编码格式"""
    has_audio: bool
    """是否包含音频 — 是否存在Audio Stream"""


@dataclass(frozen=True)
class ResolutionValidationInfo:
    """分辨率校验信息 — Generated by Stage 0.5 Resolution Filter.

    Carries the original video resolution plus the minimum-resolution
    thresholds and the pass/fail decision. This is a video-level coarse
    filter applied before any model inference (Stage 1+).
    """

    width: int
    """视频宽度 — 原始视频宽度"""
    height: int
    """视频高度 — 原始视频高度"""
    min_width: int
    """最小宽度 — 最低分辨率要求宽度"""
    min_height: int
    """最小高度 — 最低分辨率要求高度"""
    is_valid: bool
    """是否通过 — True=分辨率达标，可进入 Stage 1"""
    reject_reason: Optional[str] = None
    """拒绝原因 — 如 "resolution_too_low"；通过时为 None"""


@dataclass(frozen=True)
class StandardizedVideoInfo:
    """标准化视频信息 — Generated by Stage 1 AV Standardization.

    Fields are defined per AISDD 2.5.2.
    """

    video_path: Path
    """标准化视频路径 — FFmpeg处理后视频"""
    audio_path: Path
    """标准化音频路径 — 提取后的Audio"""
    target_fps: int
    """标准帧率 — 默认25 FPS"""
    resolution: Tuple[int, int]
    """标准分辨率 — 统一输出尺寸 (width, height)"""
    codec: str
    """编码格式 — 标准视频编码 (e.g. h264)"""


@dataclass(frozen=True)
class AudioInfo:
    """音频信息 — Generated by Stage 1 AV Standardization.

    Fields are defined per AISDD 2.5.3.
    """

    audio_path: Path
    """音频路径 — 原始提取Audio路径"""
    sample_rate: int
    """采样率 — 默认16000Hz"""
    duration: float
    """音频长度 — Audio持续时间(秒)"""
    channels: int
    """声道数 — 音频声道数量"""


@dataclass(frozen=True)
class CorrectedAudioInfo:
    """修正后音频信息 — Generated by Stage 7 A/V Sync Detection.

    Fields are defined per AISDD 2.5.4.
    """

    corrected_audio_path: Path
    """修正后音频路径 — Offset校正后的Audio文件"""
    original_audio_path: Path
    """原始音频路径 — Stage 1输出Audio"""
    offset: int
    """音频偏移量 — SyncNet检测得到的帧偏移"""
    corrected_timestamp: Tuple[float, ...]
    """修正后时间轴 — 对齐后的Audio时间信息"""
    sync_score: float
    """同步评分 — 音画同步质量"""


# ============================================================================
# Scene and Clip Data Models (AISDD 2.6)
# ============================================================================


@dataclass(frozen=True)
class SceneInfo:
    """场景信息 — Generated by Stage 2 Scene Segmentation.

    Fields are defined per AISDD 2.6.1.
    """

    scene_id: str
    """场景ID — Scene唯一标识"""
    video_id: str
    """视频ID — 所属视频"""
    start_frame: int
    """起始帧 — Scene开始位置"""
    end_frame: int
    """结束帧 — Scene结束位置"""
    start_time: float
    """开始时间 — Scene开始时间(秒)"""
    end_time: float
    """结束时间 — Scene结束时间(秒)"""
    duration: float
    """Scene时长 — Scene持续时间(秒)"""
    coarse_face_info: Optional["CoarseFaceInfo"] = None
    """粗筛人脸信息 — Stage 3 SCRFD检测结果"""
    filter_result: Optional["SceneFilterResult"] = None
    """过滤结果 — Stage 3过滤决策"""


@dataclass(frozen=True)
class CoarseFaceInfo:
    """粗筛人脸检测结果 — Generated by Stage 3 Coarse Face Screening.

    Per-Scene SCRFD detection metadata.
    Stage 3 does NOT generate aggregate statistics — that's Stage 15's role.
    """

    sampled_frame_count: int
    """采样帧数 — SCRFD实际检测的帧数"""
    face_detect_ratio: float
    """人脸检测率 — 检测到人脸帧数 / 采样帧数"""
    single_face_ratio: float
    """单人脸比例 — 单人脸帧数 / 检测到人脸帧数"""
    avg_face_confidence: float
    """平均置信度 — 所有人脸检测的平均置信度"""
    max_face_count: int
    """最大人脸数 — 单帧检测到的最大人脸数量"""


@dataclass(frozen=True)
class SceneFilterResult:
    """场景过滤决策 — Generated by Stage 3 Coarse Face Screening.

    Per-Scene filtering decision with support for multiple reject_reasons.
    Stage 3 only generates this per-sample result; Stage 15 aggregates them.
    """

    passed: bool
    """是否通过 — True=通过所有过滤规则"""
    reject_reasons: Tuple[str, ...]
    """拒绝原因列表 — 支持多个原因同时存在
    Possible values: too_short, no_face, multi_face, low_confidence
    """


@dataclass(frozen=True)
class ClipInfo:
    """Clip信息 — Generated by Stage 4 Sliding Window Cropping.

    Fields are defined per AISDD 2.6.2.
    """

    clip_id: str
    """Clip编号 — 当前Clip唯一ID"""
    scene_id: str
    """Scene编号 — 来源Scene"""
    video_id: str
    """视频ID — 来源视频"""
    start_frame: int
    """起始帧 — Clip开始帧"""
    end_frame: int
    """结束帧 — Clip结束帧"""
    start_time: float
    """起始时间 — Clip开始时间(秒)"""
    end_time: float
    """结束时间 — Clip结束时间(秒)"""
    frame_count: int
    """帧数量 — Clip包含帧数量"""
    duration: float
    """Clip长度 — Clip持续时间(秒)"""


# ============================================================================
# Face Processing Data Models (AISDD 2.7)
# ============================================================================


@dataclass(frozen=True)
class SingleFaceIdentityResult:
    """单人脸身份一致性过滤结果 — Generated by Stage 5.2.

    Uses a unified anomaly ratio: every frame that is NOT a single face
    belonging to the main track counts as an anomaly (empty, multi-face,
    or identity switch). A single threshold controls rejection.
    """

    passed: bool
    """是否通过 — anomaly_ratio <= max_identity_anomaly_ratio"""
    main_track_id: Optional[str]
    """主导track — 所有有效face中出现次数最多的track_id"""
    total_frames: int
    """总帧数"""
    anomaly_frames: int
    """异常帧数 — empty + multi + identity_switch 帧的累计数量"""
    anomaly_ratio: float
    """异常帧比例 — anomaly_frames / total_frames"""
    reject_reasons: Tuple[str, ...] = ()
    """拒绝原因 — empty_face / multi_face / identity_switch"""


@dataclass(frozen=True)
class TemporalStabilityResult:
    """时间稳定性过滤结果 — Generated by Stage 5.3.

    Analyzes frame-to-frame face motion and scale changes in a clip.
    Uses a unified anomaly ratio: each transition where center motion
    or scale change exceeds thresholds counts as one anomaly.
    """

    passed: bool
    """是否通过 — anomaly_ratio <= max_stability_anomaly_ratio"""
    average_center_motion: float
    """平均中心位移 — 相邻帧人脸中心点的平均欧氏距离(像素)"""
    max_center_motion: float
    """最大中心位移 — 相邻帧最大跳跃(像素)"""
    average_scale_change: float
    """平均尺度变化 — 相邻帧人脸面积的平均相对变化"""
    max_scale_change: float
    """最大尺度变化 — 相邻帧最大相对面积变化"""
    bbox_jump_count: int
    """bbox跳跃次数 — center_motion或scale_change超阈值的帧过渡数"""
    anomaly_ratio: float
    """异常过渡比例 — bbox_jump_count / total_transitions"""
    reject_reasons: Tuple[str, ...] = ()
    """拒绝原因 — center_motion_abnormal / scale_abnormal / bbox_jump_exceeded"""


@dataclass(frozen=True)
class FaceSequence:
    """人脸时间序列 — Generated by Stage 5 Face Localization.

    Represents the full per-frame face detection results for a single Clip.
    This is the core data unit for downstream temporal processing:
        - SyncNet consumes clip-level video/audio alignment.
        - HuBERT consumes clip-level audio segments.
        - FLAME / Gaze consume continuous face sequences.

    Fields are defined per AISDD 2.7.0.
    """

    clip_id: str
    """Clip编号 — 所属Clip唯一标识"""
    video_id: str
    """视频ID — 来源视频"""
    frames: Tuple["FrameInfo", ...]
    """帧序列 — Clip内所有帧的人脸检测结果，按frame_index升序"""
    identity_result: Optional["SingleFaceIdentityResult"] = None
    """Stage 5.2 身份一致性过滤结果 — None 表示未经过滤"""
    stability_result: Optional["TemporalStabilityResult"] = None
    """Stage 5.3 时间稳定性过滤结果 — None 表示未经过滤"""


@dataclass(frozen=True)
class FrameInfo:
    """帧信息 — Generated by Stage 5 Face Localization.

    Fields are defined per AISDD 2.7.1.
    """

    frame_index: int
    """帧编号 — 视频全局帧索引"""
    clip_id: str
    """Clip编号 — 所属Clip"""
    timestamp: float
    """时间戳 — 当前帧时间(秒)"""
    image_path: Path
    """图片路径 — 当前帧存储位置"""
    faces: Tuple["FaceInfo", ...] = ()
    """检测到的人脸列表 — 按面积降序排列"""


@dataclass(frozen=True)
class FaceInfo:
    """人脸信息 — Generated by Stage 5 Face Localization & Crop.

    Fields are defined per AISDD 2.7.2.
    """

    frame_index: int
    """帧编号 — 当前人脸对应帧"""
    face_id: str
    """人脸ID — 当前检测人脸编号（单帧内唯一）"""
    bbox: Tuple[float, float, float, float]
    """人脸框 — SCRFD 原始检测框 (x1, y1, x2, y2)"""
    landmark_5: Tuple[float, ...]
    """五点关键点 — SCRFD输出5点 (10 values)"""
    confidence: float
    """检测置信度 — 检测可靠性"""
    face_crop_path: Path
    """裁剪路径 — expanded bbox 的 raw crop 结果"""
    track_id: Optional[str] = None
    """跟踪ID — 跨帧身份标识（Stage 5.1 ByteTrack 分配），None 表示未跟踪"""
    expanded_bbox: Tuple[float, float, float, float] = (
        0.0, 0.0, 0.0, 0.0,
    )
    """扩展后裁剪框 — expand_ratio 放大后的实际 crop bbox (x1,y1,x2,y2)"""


# ============================================================================
# Landmark and Alignment Data Models
# ============================================================================


@dataclass(frozen=True)
class LandmarkInfo:
    """关键点信息 — Generated by Stage 10 High-Precision Landmark Extraction.

    Contains 106-point facial landmarks extracted by InsightFace 2d106det model.
    All landmark coordinates are in original frame coordinate space.

    Fields are defined per AISDD 2.7.3.
    """

    clip_id: str
    """Clip编号 — 所属Clip唯一标识"""
    frame_index: int
    """帧编号 — 对应视频帧"""
    face_id: str
    """人脸ID — 对应检测人脸"""
    timestamp: float
    """时间戳 — 当前帧时间(秒)"""
    landmarks_106: Tuple[float, ...]
    """106点关键点 — 展平坐标 [x0, y0, x1, y1, ..., x105, y105]，共212个float
    坐标已转换至原始frame坐标系。
    """
    image_width: int
    """原始图像宽度 — 用于坐标校验"""
    image_height: int
    """原始图像高度 — 用于坐标校验"""


@dataclass(frozen=True)
class AlignedFaceInfo:
    """人脸对齐信息 — Generated by Stage 11 Face Alignment.

    Represents the affine-aligned face normalized to a fixed resolution
    (default 256×256). Saves the full affine matrix and original image
    dimensions for future inverse warping back to original coordinates.

    Fields are defined per AISDD 2.7.4.
    """

    clip_id: str
    """Clip编号 — 所属Clip唯一标识"""
    frame_index: int
    """帧编号 — 对应视频帧"""
    face_id: str
    """人脸ID — 对应检测人脸"""
    timestamp: float
    """时间戳 — 当前帧时间(秒)"""
    aligned_face_path: Path
    """对齐后人脸路径 — 标准化Face图像 (256×256)"""
    affine_matrix: Tuple[float, ...]
    """仿射变换矩阵 — 2×3 matrix flattened: [a, b, tx, c, d, ty]
    用于 cv2.warpAffine 从原图→对齐图。
    可通过 cv2.invertAffineTransform 恢复对齐图→原图。
    """
    original_image_size: Tuple[int, int]
    """原始图像尺寸 — (height, width)，用于逆变换时还原目标尺寸"""
    aligned_resolution: Tuple[int, int]
    """对齐分辨率 — 标准人脸输出尺寸, e.g. (256, 256)"""


