@dataclass(frozen=True)
class PoseInfo:
    """姿态信息 — Generated by Stage 6 Head Pose Estimation (6DRepNet)."""

    frame_index: int
    """帧编号 — 对应视频帧"""
    face_id: str
    """人脸ID — 对应检测人脸"""
    yaw: float
    """水平旋转角 — Yaw angle (degrees)"""
    pitch: float
    """垂直旋转角 — Pitch angle (degrees)"""
    roll: float
    """平面旋转角 — Roll angle (degrees)"""
    confidence: float = 1.0
    """姿态置信度 — 模型输出置信度"""


@dataclass(frozen=True)
class PoseSequence:
    """姿态序列 — Generated by Stage 6 Head Pose Estimation.

    One PoseSequence per clip, containing per-frame head pose estimates.
    """

    clip_id: str
    """Clip编号 — 所属Clip"""
    poses: Tuple["PoseInfo", ...]
    """姿态列表 — 逐帧姿态估计结果，按frame_index升序"""


@dataclass(frozen=True)
class AVSyncInfo:
    """音画同步信息 — Generated by Stage 7 A/V Sync Detection (SyncNet).

    Preserves SyncNet raw metrics without renaming:
        - sync_lse_c: LSE-C = median(distance) - min(distance)
        - sync_lse_d: LSE-D = min(distance)
    """

    clip_id: str
    """Clip编号 — 检测的Clip"""
    offset: int
    """偏移帧数 — 检测到的音画偏移"""
    sync_lse_c: float
    """LSE-C — median(distance) - min(distance)，越高表示越可信"""
    sync_lse_d: float
    """LSE-D — min(distance)，越低表示同步越好"""
    median_distance: float = 0.0
    """中位距离 — frame-audio pairwise distance 的中位数 (debug 用)"""

    # ------------------------------------------------------------------
    # Clip 边界信息（由 Stage 7 从 ClipInfo 填充，供 Stage 7.1 生成 clip 级音频）
    # 这些字段让 Stage 7.1 无需依赖 Stage 4 的完整 audio 即可裁剪 clip 窗口：
    #   start_time = timestamp = start_frame / fps
    #   duration   = (end_frame - start_frame) / fps
    # ------------------------------------------------------------------
    start_frame: Optional[int] = None
    """起始帧 — Clip 在标准化视频中的起始帧（Stage 4 提供）"""
    end_frame: Optional[int] = None
    """结束帧 — Clip 在标准化视频中的结束帧（Stage 4 提供）"""
    fps: Optional[float] = None
    """帧率 — 检测所用帧率（frame_count/duration，或标准化目标帧率）"""
    duration: Optional[float] = None
    """Clip 时长（秒）— (end_frame - start_frame) / fps"""
    timestamp: Optional[float] = None
    """Clip 起始时间戳（秒）— start_frame / fps，即 ffmpeg -ss 裁剪起点"""


@dataclass(frozen=True)
class AVAlignmentInfo:
    """音画同步校正信息 — Generated by Stage 7.1 A/V Sync Correction.

    Contains the corrected audio path after applying SyncNet offset
    to the audio timeline.  Serves as the input for Stage 14.
    """

    clip_id: str
    """Clip编号 — 被校正的Clip"""
    original_audio_path: Path
    """原始音频路径 — Stage 1 输出的标准化音频"""
    offset_frames: int
    """偏移帧数 — SyncNet检测到的帧偏移"""
    offset_ms: float
    """偏移毫秒 — offset_frames / fps * 1000"""
    correction_applied: bool
    """是否已校正 — True=已应用校正，False=偏移在阈值内未校正"""
    fps: float
    """帧率 — 视频帧率，用于offset换算"""
    corrected_audio_path: Optional[Path] = None
    """校正后音频路径 — 仅当 correction_applied=True 时指向校正文件，否则 None"""
    aligned_audio_path: Optional[Path] = None
    """最终音频路径 — 指向实际存在且可用的 clip 级音频文件。
    下游 Stage 9.5 / Stage 14 统一读取此字段，不要判断 correction_applied。
    None 表示音频严重错位、不可用（alignment_status == "severe_offset_unavailable"）。
    - already_aligned: 裁剪后的原始音频
    - corrected: offset shift 后的音频
    - severe_offset_unavailable: None"""
    alignment_status: str = "already_aligned"
    """音频对齐状态 — 三态：
    - "already_aligned": 无需修正，裁剪原始音频即可
    - "corrected": 已执行 offset 校正
    - "severe_offset_unavailable": 严重错位，未生成可用音频"""
    raw_audio_path: Optional[Path] = None
    """裁剪后的 clip 级原始音频路径 — 从 Stage 1 完整音频按 clip 窗口
    [start_frame/fps, +duration] 裁剪，未做 offset shift。
    供 Stage 9.5 复制到最终 audio/{clip_id}.wav。
    severe_offset_unavailable 或无法解析 clip 边界时为 None。"""
    clip_start: Optional[float] = None
    """Clip 起始时间（秒）— 裁剪窗口起点（= timestamp = start_frame / fps）"""
    clip_duration: Optional[float] = None
    """Clip 时长（秒）— 裁剪窗口长度（= (end_frame - start_frame) / fps）"""


@dataclass(frozen=True)
class FaceQualityInfo:
    """人脸质量信息 — Generated by Stage 8 Quality Filtering (HyperIQA)."""

    frame_index: int
    """帧编号 — 对应视频帧"""
    face_id: str
    """人脸ID — 对应检测人脸"""
