# ============================================================================
# Final Training Data Model (AISDD 2.9)
# ============================================================================


@dataclass(frozen=True)
class TrainingSample:
    """最终训练样本 — Generated by Stage 17 Parameter Alignment & Fusion.

    clip-level 时间序列样本包: 每个 Stage4 clip 生成一个样本 (sample_id := clip_id)。
    所有模态按同一帧轴 T 对齐 (见 docs/Stage17_Design_Review.md §4)。

    与旧版「单帧标量」结构的差异:
      - visual_feature [T,112] float32 = expcode[100] + posecode[6] + gaze_vector[6]
      - audio_feature  [T,768] float32 (HuBERT hidden states, 与视觉帧 nearest-timestamp 对齐)
      - frame_index / timestamps / dropout_mask / audio_match_idx 均为 [T] 对齐数组
      - metadata 由旧 tuple-pairs 升级为 dict (旧 tuple 输入自动转换, 保持兼容)
    旧单帧字段 (sample_id/video_clip/face_sequence/flame_feature/gaze_feature) 保留为
    可选遗留字段, 仅供向后兼容; 新代码应使用 clip_id 与数组字段。
    """

    clip_id: str = ""
    """样本/Clip ID — 每个 Stage4 clip 生成一个训练样本 (sample_id := clip_id)"""
    visual_feature: np.ndarray = field(
        default_factory=lambda: np.zeros((0, 112), dtype=np.float32)
    )
    """视觉特征 — [T,112] float32 = expression[100] + pose[6] + gaze[6]"""
    audio_feature: np.ndarray = field(
        default_factory=lambda: np.zeros((0, 768), dtype=np.float32)
    )
    """音频特征 — [T,768] float32, 与视觉帧按 timestamp 最近邻对齐"""
    frame_index: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=np.int32))
    """视频帧号 — [T] int32, 以 FLAME 的 frame_index 为锚点"""
    timestamps: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=np.float32))
    """时间戳 — [T] float32, 标准化视频绝对秒"""
    valid_length: Optional[int] = None
    """有效帧数 — 三模态齐全且 |Δt| 合格的帧数。
    None 表示未标定 (构造时按 T 自动填充); 显式 0 表示「全缺失样本」,
    0 会原样保留 (区别于自动填充)。"""
    dropout_mask: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=bool))
    """缺失帧掩码 — [T] bool; True 表示该帧经 forward-fill 补齐, 训练侧可丢弃"""
    audio_match_idx: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=np.int32))
    """音频匹配索引 — [T] int32, 每帧对应原始 audio feature 的索引; -1 表示未匹配"""
    metadata: Union[Dict[str, Any], Tuple[Tuple[str, str], ...]] = field(
        default_factory=dict
    )
    """元数据 — 溯源字段 (sample_id/clip_id/video_id/scene_id/fps/start_frame 等);
    兼容旧 Tuple[Tuple[str, str], ...] 输入, 自动转换为 dict。"""

    # ---- 以下为遗留字段 (backward compatibility), 新代码请勿使用 ----
    sample_id: Optional[str] = None
    """[DEPRECATED] 旧单帧样本ID — 兼容旧调用; 新代码用 clip_id"""
    video_clip: Optional[Path] = None
    """[DEPRECATED] 旧视频Clip路径 — 兼容旧调用"""
    face_sequence: Optional[Path] = None
    """[DEPRECATED] 旧人脸序列路径 — 兼容旧调用"""
    flame_feature: Optional[Tuple[float, ...]] = None
    """[DEPRECATED] 旧FLAME参数 (expcode + posecode) — 兼容旧调用"""
    gaze_feature: Optional[Tuple[float, ...]] = None
    """[DEPRECATED] 旧Gaze参数 (6 dims) — 兼容旧调用"""

    def __post_init__(self) -> None:
        """规范化数组 dtype/shape, 并做 T 轴一致性校验。

        - visual/audio 特征强制 float32 2D [T,D]; 若传入 1D 且长度恰为 D
          (旧单帧 tuple 语义) 则重塑为 [1,D]。
        - frame_index/timestamps/audio_match_idx → int32/float32/int32;
          dropout_mask → bool。
        - T 轴一致性: 当 visual/audio 之一有帧时, 另一为空则自动零填充对齐;
          两者都有帧但 T 不一致时报错。其余 [T] 数组长度必须为 T,
          空数组 (size 0) 按合理默认自动填充。
        - valid_length 缺省 (None) 时在 T>0 下自动置为 T; 显式传 0 表示
          全缺失样本, 0 原样保留 (不自动填充)。
        - sample_id 缺省时自动继承 clip_id (旧代码读取 ts.sample_id 不落空)。
        """
        vis = self._as_array(self.visual_feature, np.float32, 2, 112, "visual_feature")
        aud = self._as_array(self.audio_feature, np.float32, 2, 768, "audio_feature")

        # 单模态有帧 → 另一模态零填充对齐 (兼容旧单帧构造)
        if vis.shape[0] == 0 and aud.shape[0] > 0:
            vis = np.zeros((aud.shape[0], 112), dtype=np.float32)
        elif aud.shape[0] == 0 and vis.shape[0] > 0:
            aud = np.zeros((vis.shape[0], 768), dtype=np.float32)
        elif vis.shape[0] != aud.shape[0]:
            raise ValueError(
                f"TrainingSample T-axis mismatch: visual_feature has {vis.shape[0]} "
                f"frames, audio_feature has {aud.shape[0]} frames"
            )
        t = vis.shape[0]

        frame_index = self._as_axis(self.frame_index, np.int32, t, "frame_index")
        timestamps = self._as_axis(self.timestamps, np.float32, t, "timestamps")
        dropout_mask = self._as_axis(self.dropout_mask, np.bool_, t, "dropout_mask")
        audio_match_idx = self._as_axis(self.audio_match_idx, np.int32, t, "audio_match_idx")

        valid_length = self.valid_length
        if valid_length is None:
            # 未标定: T>0 自动填充为 T (兼容旧调用), 空样本为 0
            valid_length = t if t > 0 else 0
        valid_length = int(valid_length)

        metadata = self.metadata
        if isinstance(metadata, (list, tuple)):
            metadata = {str(k): v for k, v in metadata}
        elif metadata is None:
            metadata = {}
        if not isinstance(metadata, dict):
            raise ValueError(
                "TrainingSample.metadata must be a dict or a sequence of "
                f"(key, value) pairs, got {type(metadata).__name__}"
            )

        sample_id = self.sample_id if self.sample_id is not None else self.clip_id

        object.__setattr__(self, "visual_feature", vis)
        object.__setattr__(self, "audio_feature", aud)
        object.__setattr__(self, "frame_index", frame_index)
        object.__setattr__(self, "timestamps", timestamps)
        object.__setattr__(self, "dropout_mask", dropout_mask)
        object.__setattr__(self, "audio_match_idx", audio_match_idx)
        object.__setattr__(self, "valid_length", valid_length)
        object.__setattr__(self, "metadata", metadata)
        object.__setattr__(self, "sample_id", sample_id)

    @staticmethod
    def _as_array(
        value: Any,
        dtype: Any,
        ndim: int,
        dim: int,
        name: str,
    ) -> np.ndarray:
        """将输入规范化为 [T, D] 或 [T] 的 ndarray。

        兼容旧单帧 tuple 输入: 1D 且长度恰为 D 时视为单帧, 重塑为 [1, D]。
        """
        if value is None:
            shape = (0, dim) if ndim == 2 else (0,)
            return np.zeros(shape, dtype=dtype)
        arr = np.asarray(value, dtype=dtype)
        if arr.size == 0:
            shape = (0, dim) if ndim == 2 else (0,)
            return np.zeros(shape, dtype=dtype)
        if ndim == 2 and arr.ndim == 1 and arr.shape[0] == dim:
            arr = arr.reshape((1, dim))
        if arr.ndim != ndim:
            raise ValueError(
                f"TrainingSample.{name} must be {ndim}D, got shape {arr.shape}"
            )
        if ndim == 2 and arr.shape[1] != dim:
            raise ValueError(
                f"TrainingSample.{name} feature dim must be {dim}, got {arr.shape[1]}"
            )
        return np.asarray(arr, dtype=dtype)

    @staticmethod
    def _as_axis(value: Any, dtype: Any, t: int, name: str) -> np.ndarray:
        """将 [T] 对齐数组规范化为目标 dtype, 并校验长度 == T。

        当 T>0 且输入为空 (size 0) 时按合理默认填充:
          frame_index → arange(T); audio_match_idx → 全 -1;
          dropout_mask → 全 False; timestamps → 全 0。
        """
        if value is None:
            value = []
        arr = np.asarray(value, dtype=dtype).reshape(-1)
        if t == 0:
            return arr
        if arr.size == 0:
            if name == "frame_index":
                return np.arange(t, dtype=dtype)
            if name == "audio_match_idx":
                return np.full(t, -1, dtype=dtype)
            if name == "dropout_mask":
                return np.zeros(t, dtype=dtype)
            return np.zeros(t, dtype=dtype)  # timestamps
        if arr.size != t:
            raise ValueError(
                f"TrainingSample.{name} length {arr.size} != T={t}"
            )
        return arr

    @classmethod
    def from_legacy(
        cls,
        sample_id: str,
        video_clip: Optional[Path] = None,
        face_sequence: Optional[Path] = None,
        flame_feature: Optional[Tuple[float, ...]] = None,
        gaze_feature: Optional[Tuple[float, ...]] = None,
        audio_feature: Optional[Tuple[float, ...]] = None,
        metadata: Optional[Tuple[Tuple[str, str], ...]] = None,
    ) -> "TrainingSample":
        """旧单帧 API → clip-level 样本包 (单帧 T=1) 的迁移工厂。

        供旧调用方平滑迁移; 新代码请直接使用数组字段构造。
        visual_feature 由 flame_feature (pad 至 106) + gaze_feature (6) 拼成 112 维。
        """
        vis = np.zeros((1, 112), dtype=np.float32)
        if flame_feature is not None:
            vals = np.asarray(list(flame_feature), dtype=np.float32)
            if vals.size > 106:
                raise ValueError("flame_feature must have at most 106 dims")
            vis[0, : vals.size] = vals
        if gaze_feature is not None:
            vals = np.asarray(list(gaze_feature), dtype=np.float32)
            if vals.size != 6:
                raise ValueError("gaze_feature must have 6 dims")
            vis[0, 106:112] = vals

        aud = np.zeros((1, 768), dtype=np.float32)
        if audio_feature is not None:
            vals = np.asarray(list(audio_feature), dtype=np.float32)
            if vals.size != 768:
                raise ValueError("audio_feature must have 768 dims")
            aud[0, :] = vals

        meta: Dict[str, Any] = dict(metadata or {})
        meta.setdefault("sample_id", sample_id)
        return cls(
            clip_id=sample_id,
            visual_feature=vis,
            audio_feature=aud,
            frame_index=np.array([0], dtype=np.int32),
            timestamps=np.array([0.0], dtype=np.float32),
            valid_length=1,
            dropout_mask=np.array([False], dtype=bool),
            audio_match_idx=np.array([-1], dtype=np.int32),
            metadata=meta,
            sample_id=sample_id,
            video_clip=video_clip,
            face_sequence=face_sequence,
            flame_feature=flame_feature,
            gaze_feature=gaze_feature,
        )

